INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "齐藏珍", "aliases": ["齊藏珍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将军。948年正月与王景崇率禁军迎接回鹘贡使并经略关西。其后建议杀赵思绾，王景崇没有听从。生卒年未载。", "biography": null, "status": "draft", "id": "654b2549-6bd7-5790-80f4-0c95bd3781b3"}, {"name": "李恕（赵匡赞判官）", "aliases": ["李恕（晋昌判官）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋昌节度判官，曾在赵延寿幕下受信任，后随其子赵匡赞。948年劝赵匡赞不要入蜀，代其入朝申明归降后蜀的原因，请求入朝，获刘知远同意。与其他年代同名人物是否有关，未作无证合并。生卒年未载。", "biography": null, "status": "draft", "id": "422f34ce-272d-50ea-823e-b7102499ef26"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "薛温", "aliases": ["薛溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越匡武都头。948年正月奉钱弘俶命，率亲兵守护被废的钱弘倧，并受密令抵御异常处置。生卒年未载。", "biography": null, "status": "draft", "id": "adc72ad7-c8b7-5019-90f0-35e7952d1954"}, {"name": "刘承训", "aliases": ["劉承訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的儿子。947年九月刘知远诏赴澶、魏劳军时，任命他为东京留守。生卒年尚未录入。", "biography": null, "status": "draft", "id": "4e08b6fa-2adc-5da7-b83b-0448f2cda108"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "张虔钊", "aliases": ["張虔釗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张虔钊。", "biography": null, "status": "draft", "id": "b4b03cda-5958-57ef-b1ca-a5c8e1fb4985"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

